 bool Pass=true;auto Expect=[&](bool V,const TCHAR* Name){Pass &= V;Check(V,Name);};auto* Identity=Cast<UDasAuthoredInterfaceClass>(Interface);Expect(Identity && Identity->StableId==TEXT("authoredinterface_")+FPaths::GetBaseFilename(Script).RightChop(15)+TEXT(".CounterContract") && !Identity->ContractJson.IsEmpty(),TEXT("authored_interface_persistent_identity"));Expect(Actor->GetClass()->ImplementsInterface(Interface),TEXT("authored_interface_native_membership"));
